def hydrate_time(nanoseconds, tz):
    seconds = nanoseconds // 1_000_000_000
    ns_remainder = nanoseconds % 1_000_000_000
    microseconds = ns_remainder // 1_000

    total_seconds_in_day = seconds % 86400

    hours, remainder = divmod(total_seconds_in_day, 3600)
    minutes, seconds = divmod(remainder, 60)

    naive_dt = datetime.datetime(1970, 1, 1, int(hours), int(minutes), int(seconds), int(microseconds))

    if tz is not None:
        if isinstance(tz, str):
            tz = pytz.timezone(tz)
        aware_dt = tz.localize(naive_dt)
    else:
        aware_dt = pytz.utc.localize(naive_dt)

    return aware_dt.time()

