def xargs(command, color=False, target_concurrency=1):
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip()]
    if not lines:
        return

    batches = [[line] for line in lines]

    def run_batch(batch):
        full_cmd = command + batch
        if os.name == 'posix' and color:
            pty.spawn(full_cmd)
        else:
            subprocess.run(full_cmd, check=False)

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = [executor.submit(run_batch, batch) for batch in batches]
        for future in futures:
            future.result()

