def mru_cache(maxsize=128):
    def decorator(func):
        import functools
        import collections

        cache = {}
        history = collections.deque()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                # Move the accessed item to the end of the deque
                try:
                    history.remove(key)
                except ValueError:
                    pass
                history.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Remove the most recently used item (last in deque)
                while history:
                    k = history.pop()
                    if k in cache:
                        del cache[k]
                        break
            cache[key] = result
            history.append(key)
            return result

        return wrapper

    return decorator

