def cachedmethod(func):
    def wrapper(*args, **kwargs):
        instance = args[0]
        cache_name = f'_cachedmethod_{func.__name__}'
        cache = getattr(instance, cache_name, None)
        if cache is None:
            cache = {}
            setattr(instance, cache_name, cache)
        key = (args[1:], frozenset(kwargs.items()))
        if key in cache:
            return cache[key]
        result = func(*args, **kwargs)
        cache[key] = result
        return result
    return wrapper

