def extostr(cls, e, max_level=30, max_path_level=5):
    tb = traceback.TracebackException(type(e), e, e.__traceback__)
    lines = tb.format(limit=max_level)
    for i in range(len(lines)):
        if lines[i].startswith('File '):
            start = lines[i].find('"') + 1
            end = lines[i].find('"', start)
            if start > 0 and end > start:
                original_path = lines[i][start:end]
                parts = []
                path = original_path
                while True:
                    head, tail = os.path.split(path)
                    if tail == path:
                        parts.append(path)
                        break
                    parts.append(tail)
                    path = head
                parts.reverse()
                if len(parts) > max_path_level:
                    truncated_parts = parts[-max_path_level:]
                    if os.path.isabs(original_path):
                        truncated_path = '.../' + os.path.join(*truncated_parts)
                    else:
                        truncated_path = '.../' + os.path.join(*truncated_parts)
                    lines[i] = lines[i][:start] + truncated_path + lines[i][end+1:]
    return ''.join(lines)

