def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return {}

    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        else:
            val1 = d1[key]
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict) and (level == -1 or level > 1):
                sub_diff = difference(val1, val2, level=(level - 1) if level != -1 else -1)
                if sub_diff:
                    result[key] = sub_diff
            elif val1 != val2:
                result[key] = val1
    return result

import bisect

class Histogram:
    def fill(self, coord, weight=1.0):
        if len(coord) != self.dim:
            return
        for i in range(self.dim):
            x = coord[i]
            edges_i = self.edges[i]
            if x < edges_i[0] or x >= edges_i[-1]:
                return
        indices = []
        for i in range(self.dim):
            x = coord[i]
            edges_i = self.edges[i]
            idx = bisect.bisect_right(edges_i, x) - 1
            indices.append(idx)
        bin_index = tuple(indices)
        self.bins[bin_index] += weight

