def absorb(self, args):
    new_args = []
    for expr in args:
        redundant = False
        for other in args:
            if expr is other:
                continue
            if (self._pyoperator is operator.and_ and other in expr) or (self._pyoperator is operator.or_ and expr in other):
                redundant = True
                break
            elif self._pyoperator is operator.and_ and other._pyoperator is operator.or_ and expr.NOT in other.args:
                redundant = True
                break
            elif self._pyoperator is operator.or_ and other._pyoperator is operator.and_ and expr.NOT in other.args:
                redundant = True
                break
        if not redundant:
            new_args.append(expr)
    return new_args

