def _fromutc(self, dt):
    offset = self.utcoffset(dt)
    local = dt - offset
    local = local.replace(tzinfo=self)
    if self._is_ambiguous(local):
        d = local.replace(fold=1)
        od = self.utcoffset(d)
        if d + od == dt:
            return d
        else:
            return local.replace(fold=0)
    else:
        return local

